// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        address actor = address(0xBEEF);
        amount1 = bound(amount1, 1 ether, 10 ether);
        amount2 = bound(amount2, 1 ether, 10 ether);
        unlockTime1 = bound(unlockTime1, 0, block.timestamp);
        unlockTime2 = bound(unlockTime2, 0, block.timestamp);
        vm.deal(actor, amount1 + amount2 + 1 ether);

        vm.prank(actor);
        c.Put{value: amount1}(unlockTime1);

        vm.prank(actor);
        c.Collect(amount1);

        vm.prank(actor);
        c.Put{value: amount2}(unlockTime2);

        bool ok = true;
        try c.Collect(amount2) { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
